import Cocoa
import AVFoundation
import UniformTypeIdentifiers
enum ScreenSaverVideo {
 static var configuredURL:URL?{let defaults=UserDefaults.standard;guard defaults.bool(forKey:"saverVideoEnabled"),let path=defaults.string(forKey:"saverVideoPath"),FileManager.default.isReadableFile(atPath:path) else{return nil};return URL(fileURLWithPath:path)}
 static func playable(_ url:URL)->Bool{let asset=AVURLAsset(url:url);return asset.isPlayable && !asset.tracks(withMediaType:.video).isEmpty}
 static func install(_ url:URL)throws{guard playable(url) else{throw NSError(domain:"ShiQiVideo",code:1,userInfo:[NSLocalizedDescriptionKey:"该文件无法作为视频播放，请选择可播放的 MP4 文件。"])};let dir=FileManager.default.urls(for:.applicationSupportDirectory,in:.userDomainMask)[0].appendingPathComponent("ShiQi/ScreenSaver",isDirectory:true);try FileManager.default.createDirectory(at:dir,withIntermediateDirectories:true);let dest=dir.appendingPathComponent(UUID().uuidString+".mp4");try FileManager.default.copyItem(at:url,to:dest);UserDefaults.standard.set(dest.path,forKey:"saverVideoPath");UserDefaults.standard.set(true,forKey:"saverVideoEnabled")}
}
extension Delegate {
 @objc func chooseSaverVideo(){closeInlinePanel();let panel=NSOpenPanel();panel.allowedContentTypes=[.mpeg4Movie];panel.allowsMultipleSelection=false;panel.canChooseDirectories=false;NSApp.activate(ignoringOtherApps:true);panel.begin{response in guard response == .OK,let url=panel.url else{return};DispatchQueue.global(qos:.utility).async{do{try ScreenSaverVideo.install(url);DispatchQueue.main.async{self.syncMenuChecks();if self.restOverlay.isActive{self.restOverlay.updateScene(image:self.lastImage,poem:self.poemText)}}}catch{DispatchQueue.main.async{self.reply("视频设置失败：\(error.localizedDescription)")}}}}}
 func setSaverVideoEnabled(_ enabled:Bool){if enabled,UserDefaults.standard.string(forKey:"saverVideoPath")==nil{chooseSaverVideo();return};UserDefaults.standard.set(enabled,forKey:"saverVideoEnabled");syncMenuChecks();if restOverlay.isActive{restOverlay.updateScene(image:lastImage,poem:poemText)}}
 func runVideoTests(){guard let index=CommandLine.arguments.firstIndex(of:"--video-test"),CommandLine.arguments.count>index+1 else{fatalError("Video path required")};let url=URL(fileURLWithPath:CommandLine.arguments[index+1]);assert(ScreenSaverVideo.playable(url));let controller=RestOverlayController{};controller.videoOverride=url;controller.startScreensaver(image:lastImage,poem:poemText,present:false,frames:[NSRect(x:0,y:0,width:1280,height:800),NSRect(x:1280,y:0,width:1024,height:768)]);assert(controller.videoPlayers.count==2 && controller.videoLoopers.count==2 && controller.videoPlayers.allSatisfy{$0.isMuted});DispatchQueue.main.asyncAfter(deadline:.now()+3){assert(controller.videoPlayers.allSatisfy{CMTimeGetSeconds($0.currentTime())>0});controller.finish();assert(controller.videoPlayers.isEmpty && controller.videoLoopers.isEmpty);controller.start(seconds:60,image:nil,poem:"",present:false,frames:[NSRect(x:0,y:0,width:1280,height:800)]);assert(controller.countdown != nil && controller.videoPlayers.count==1);controller.dismissForLock();assert(!controller.isActive && controller.videoPlayers.isEmpty);print("{\"success\":true,\"checks\":[\"provided MP4 decodes and plays\",\"two screen muted looping players\",\"exit releases players\",\"rest video retains countdown\",\"lock dismissal stops video\"]}");fflush(stdout);NSApp.terminate(nil)}}
}
